// Generated by vibelang from e2e/run-prerequisites.ts; the migrate flow writes it again with each batch.
import { expect, test } from "@playwright/test";
import { CLOUD_RUNS_ROUTE, remoteRunRoute } from "../src/features/runs/contract.js";
import { repoFlowsRoute, repoRunsRoute } from "../src/features/actions/contract.js";
import { me, writeHeaders } from "./target.js";
/** Retained history is read through the person's API, never inserted into an engine's journal. */
export const inspectRun = async (request, execution) => {
    const response = await request.get(`${remoteRunRoute(execution)}?limit=1`);
    expect(response.status(), "the retained run must be visible to the test account").toBe(200);
    return await response.json();
};
/** A failure with real attempted work and a downstream action that never ran. */
const hasFailure = (inspection) => inspection.steps.some(step => step.status === "failed" && step.attempts.some(attempt => attempt.state === "failed" && attempt.error !== null)) &&
    inspection.steps.some(step => step.action !== null && step.attempts.length === 0 && (step.status === "skipped" || step.status === "failed"));
/** Select the newest suitable real failure each time, so routine production history cannot age a pinned id out. */
export const failedHistory = async (request) => {
    const response = await request.get(`${CLOUD_RUNS_ROUTE}?limit=50`);
    expect(response.status(), "the product must list this person's real Cloud runs").toBe(200);
    const { runs } = await response.json();
    const pinned = process.env.E2E_FAILED_RUN;
    const candidates = runs.filter(run => run.status === "failed" && (!pinned || run.runId === pinned));
    for (const run of candidates) {
        const inspection = await inspectRun(request, run.runId);
        if (!hasFailure(inspection))
            continue;
        // TODO flows handle a work failure and then complete their failure handler. The list's work
        // status is Failed; the engine's completed root does not erase the recorded action failure.
        await test.info().attach("failed-history", { body: JSON.stringify({
                execution: run.runId, workStatus: run.status, engineStatus: inspection.run.status,
                failures: inspection.steps.filter(step => step.attempts.some(attempt => attempt.state === "failed"))
                    .map(step => ({ action: step.action, attempts: step.attempts.length })),
            }), contentType: "application/json" });
        return run.runId;
    }
    throw new Error("No visible real failed run has recorded failure attempts and undispatched actions. Create a failed TODO through the product; E2E_FAILED_RUN may pin it. Never fabricate journal history.");
};
/** Use retained real history, or launch the checked-in scratch fixture through the same API as its Run button. */
export const repositoryHistory = async (request) => {
    const response = await request.get(`${CLOUD_RUNS_ROUTE}?limit=50`);
    expect(response.status()).toBe(200);
    const { runs } = await response.json();
    const pinned = process.env.E2E_REPOSITORY_RUN;
    const existing = runs.find(run => run.kind === "repo" && (!pinned || run.runId === pinned));
    if (existing) {
        const inspection = await inspectRun(request, existing.runId);
        expect(inspection.journal.events.length, "retained repository history has real engine records").toBeGreaterThan(0);
        await test.info().attach("repository-history", { body: JSON.stringify({ execution: existing.runId, repository: existing.repo, created: false }), contentType: "application/json" });
        return existing.runId;
    }
    expect(pinned, "a pinned repository execution must still be in the product's personal Runs list").toBeFalsy();
    const repository = process.env.E2E_REPO_FLOWS_REPOSITORY ?? process.env.E2E_FACTORY_REPOSITORY;
    expect(repository, "configure a test-account scratch repository for repository flow creation").toMatch(/^[\w.-]+\/[\w.-]+$/);
    const [owner, name] = repository.split("/");
    expect(owner.toLowerCase(), "fixture creation is restricted to the test account's own scratch repository").toBe(me().login.toLowerCase());
    const flows = await request.get(repoFlowsRoute(owner, name));
    expect(flows.status(), "No retained repository run exists. Enable REPO_FLOWS and allow the test-account scratch repository in REPO_FLOWS_REPOSITORIES; its default branch needs e2e/fixtures/ci-repo's manual hand flow.").toBe(200);
    const available = await flows.json();
    expect(available.flows.some(flow => flow.name === "hand"), "the scratch fixture must expose its real manual hand flow").toBe(true);
    const started = await request.post(repoRunsRoute(owner, name), {
        headers: writeHeaders(),
        data: { id: crypto.randomUUID(), flow: "hand", ref: available.defaultBranch, input: { greeting: "History fixture", wait: "1" } },
    });
    expect([200, 202], "the product must admit the real repository run").toContain(started.status());
    const { runId } = await started.json();
    await expect.poll(async () => {
        const receipt = await request.get(`${remoteRunRoute(runId)}?limit=1`);
        if (receipt.status() === 404)
            return false; // Admitted before the engine starts.
        expect(receipt.status()).toBe(200);
        return (await receipt.json()).journal.events.length > 0;
    }, { timeout: 60_000, message: "the admitted repository run must produce real engine history" }).toBe(true);
    await test.info().attach("repository-history", { body: JSON.stringify({ execution: runId, repository, created: true }), contentType: "application/json" });
    return runId;
};
